import numpy as np
def equation(eps, T, params):
    a,b,c,d,e,f,g,k,p,q = params[:10]
    return (a+b*T+c*T**2) + (d+e*T)*eps**(p+f*T) + g*np.exp(-k*eps) + q*np.log(eps)

